/**
 * Minimal pacs.004 parser to populate TBL_CBR_TRANSACTION from a raw XML request.
 */
@Service
@RequiredArgsConstructor
public class Pacs004ParserService {

    private static final Logger LOG = LoggerFactory.getLogger(Pacs004ParserService.class);

    private static final String NS_MAIN = "urn:iso:std:iso:20022:tech:xsd:pacs.004.001.09.GSE.001";
    private static final String NS_ISO = "urn:iso:std:iso:20022:tech:xsd:pacs.004.001.09";
    private static final Pattern PACS_CODE_PATTERN = Pattern.compile("pacs\\.(\\d{3})");

    private final CbrTransactionRepository transactionRepository;
    private final CbrTransactionRequestRepository requestRepository;
    private final GetClientForSepaService getClientForSepaService;

    @Transactional
    public CbrTransaction parseAndSave(CbrTransactionRequest request) {
        try {
            Document doc = buildDocument(request.getRawXml());
            XPath xpath = buildXPath();

            MessageType messageType = resolveMessageType(doc);
            String msgId = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:GrpHdr/iso:MsgId");
            String creDtTm = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:GrpHdr/iso:CreDtTm");
            String rtrId = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:TxInf/iso:RtrId");
            String txId = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:TxInf/iso:TxId");
            String orgnlTxId = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxId");
            String orgnlEndToEndId = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlEndToEndId");
            String settlementDateStr = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:GrpHdr/iso:IntrBkSttlmDt");
            String settlementAmountStr = text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:TxInf/iso:RtrdIntrBkSttlmAmt");
            String settlementCurrency = attr(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:RtrdIntrBkSttlmAmt/@Ccy");
            String originalSettlementAmountStr = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlIntrBkSttlmAmt");
            String originalSettlementCurrency = attr(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlIntrBkSttlmAmt/@Ccy");

            String debtorAgent = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:CdtrAgt/iso:FinInstnId/iso:BICFI");
            String creditorAgent = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:DbtrAgt/iso:FinInstnId/iso:BICFI");

            String debtorName = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:Nm"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:Pty/iso:Nm"));
            String creditorName = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:Nm"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:Pty/iso:Nm"));

            String debtorIban = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:CdtrAcct/iso:Id/iso:IBAN");
            String creditorIban = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:DbtrAcct/iso:Id/iso:IBAN");
            String chargeBearer = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:ChrgBr");
            String remittanceInfo = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:RmtInf/iso:Ustrd"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:RmtInf/iso:Strd"));

            String debtorPostalAddress = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:PstlAdr"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:Pty/iso:PstlAdr"));
            String debtorTown = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:PstlAdr/iso:TwnNm"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:Pty/iso:PstlAdr/iso:TwnNm"));
            String debtorCountry = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:PstlAdr/iso:Ctry"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:Pty/iso:PstlAdr/iso:Ctry"));
            String debtorAddress = firstNonBlank(
                    joinText(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:PstlAdr/iso:AdrLine",
                            " "),
                    joinText(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Cdtr/iso:Pty/iso:PstlAdr/iso:AdrLine",
                            " "));

            String creditorPostalAddress = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:PstlAdr"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:Pty/iso:PstlAdr"));
            String creditorTown = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:PstlAdr/iso:TwnNm"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:Pty/iso:PstlAdr/iso:TwnNm"));
            String creditorCountry = firstNonBlank(
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:PstlAdr/iso:Ctry"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:Pty/iso:PstlAdr/iso:Ctry"));
            String creditorAddress = firstNonBlank(
                    joinText(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:PstlAdr/iso:AdrLine",
                            " "),
                    joinText(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:TxInf/iso:OrgnlTxRef/iso:Dbtr/iso:Pty/iso:PstlAdr/iso:AdrLine",
                            " "));

            String directionRaw = firstNonBlank(
                    text(xpath, doc, "/urn:Document/urn:PmtRtr/urn:TxInf/urn:Extensions/urn:TxType"),
                    text(xpath, doc,
                            "/urn:Document/urn:PmtRtr/urn:GrpHdr/urn:Extensions/*[local-name()='Direction']"));
            TransferDirection direction = parseDirection(directionRaw);
            String debtorAccountNo = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/urn:Extensions/urn:DebtorAccountNumber");
            String creditorAccountNo = text(xpath, doc,
                    "/urn:Document/urn:PmtRtr/urn:TxInf/urn:Extensions/urn:CreditorAccountNumber");

            LocalDateTime sourceReceivedAt = parseDateTimeOrNow(creDtTm);
            LocalDate settlementDate = parseDateOrToday(settlementDateStr);
            BigDecimal settlementAmount = parseAmount(settlementAmountStr);
            BigDecimal originalSettlementAmount = parseAmount(originalSettlementAmountStr);

            String callReplyRef = firstNonBlank(rtrId, txId, orgnlTxId, msgId, UUID.randomUUID().toString());
            String paymentReference = firstNonBlank(txId, orgnlTxId, rtrId, msgId, callReplyRef);

            CbrTransaction txn = new CbrTransaction();
            txn.setRequest(request);
            txn.setCallReplyRef(callReplyRef);
            txn.setMessageType(messageType != null ? messageType : MessageType.P4);
            txn.setDirection(direction != null ? direction : TransferDirection.OUT);
            txn.setPaymentReference(paymentReference);
            txn.setOriginalTransactionId(orgnlTxId);
            txn.setOriginalChannelReference(orgnlEndToEndId);
            txn.setSourceReceivedAt(sourceReceivedAt);
            txn.setSettlementAmount(settlementAmount);
            txn.setSettlementCurrency(notBlank(settlementCurrency) ? settlementCurrency : "XXX");
            txn.setOriginalSettlementAmount(originalSettlementAmount);
            txn.setOriginalSettlementCurrency(notBlank(originalSettlementCurrency) ? originalSettlementCurrency : "XXX");
            txn.setSettlementDate(settlementDate);
            txn.setOriginalPaymentType("SEPA");
            txn.setDebtorAgent(debtorAgent);
            txn.setCreditorAgent(creditorAgent);
            txn.setDebtorName(debtorName);
            txn.setCreditorName(creditorName);
            txn.setDebtorIban(debtorIban);
            txn.setCreditorIban(creditorIban);
            txn.setDebtorAccountNo(debtorAccountNo);
            txn.setCreditorAccountNo(creditorAccountNo);
            txn.setChargeBearer(chargeBearer);
            txn.setRemittanceInfo(remittanceInfo);
            txn.setDebtorPostalAddress(debtorPostalAddress);
            txn.setDebtorTown(debtorTown);
            txn.setDebtorCountry(debtorCountry);
            txn.setDebtorAddress(debtorAddress);
            txn.setCreditorPostalAddress(creditorPostalAddress);
            txn.setCreditorTown(creditorTown);
            txn.setCreditorCountry(creditorCountry);
            txn.setCreditorAddress(creditorAddress);
            txn.setStatus("S2");

            CbrTransaction saved = transactionRepository.save(txn);

            request.setStatus("S2");
            request.setErrorMessage(null);
            requestRepository.save(request);

            triggerClientEnrichment(saved, request.getId());

            LOG.info("Parsed pacs.004 request id={} into transaction id={} (RtrId={}, MsgId={})",
                    request.getId(), saved.getId(), rtrId, msgId);
            return saved;
        } catch (Exception e) {
            request.setStatus("S1");
            request.setErrorMessage(e.getMessage());
            requestRepository.save(request);
            LOG.error("Failed to parse pacs.004 request id={}", request.getId(), e);
            throw new IllegalStateException("Failed to parse pacs.004", e);
        }
    }

    private void triggerClientEnrichment(CbrTransaction txn, Long requestId) {
        if (txn == null || requestId == null) {
            return;
        }
        if (txn.getDirection() == TransferDirection.IN) {
            if (notBlank(txn.getCreditorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getCreditorAccountNo(), requestId, GetClientForSepaService.AccountRole.CREDITOR);
            }
            return;
        }
        if (txn.getDirection() == TransferDirection.OUT) {
            if (notBlank(txn.getDebtorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getDebtorAccountNo(), requestId, GetClientForSepaService.AccountRole.DEBTOR);
            }
            return;
        }
        if (txn.getDirection() == TransferDirection.INT) {
            if (notBlank(txn.getCreditorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getCreditorAccountNo(), requestId, GetClientForSepaService.AccountRole.CREDITOR);
            }
            if (notBlank(txn.getDebtorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getDebtorAccountNo(), requestId, GetClientForSepaService.AccountRole.DEBTOR);
            }
        }
    }

    private Document buildDocument(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        try (StringReader reader = new StringReader(xml)) {
            return factory.newDocumentBuilder().parse(new InputSource(reader));
        }
    }

    private XPath buildXPath() {
        XPath xpath = XPathFactory.newInstance().newXPath();
        xpath.setNamespaceContext(new NamespaceContext() {
            @Override
            public String getNamespaceURI(String prefix) {
                if ("urn".equals(prefix)) {
                    return NS_MAIN;
                }
                if ("iso".equals(prefix)) {
                    return NS_ISO;
                }
                return null;
            }

            @Override
            public String getPrefix(String namespaceURI) {
                if (NS_MAIN.equals(namespaceURI)) {
                    return "urn";
                }
                if (NS_ISO.equals(namespaceURI)) {
                    return "iso";
                }
                return null;
            }

            @Override
            public Iterator<String> getPrefixes(String namespaceURI) {
                return null;
            }
        });
        return xpath;
    }

    private String text(XPath xpath, Object node, String expr) throws XPathExpressionException {
        String value = (String) xpath.evaluate(expr, node, XPathConstants.STRING);
        return notBlank(value) ? value.trim() : null;
    }

    private String attr(XPath xpath, Object node, String expr) throws XPathExpressionException {
        String value = (String) xpath.evaluate(expr, node, XPathConstants.STRING);
        return notBlank(value) ? value.trim() : null;
    }

    private String joinText(XPath xpath, Object node, String expr, String separator) throws XPathExpressionException {
        NodeList nodes = (NodeList) xpath.evaluate(expr, node, XPathConstants.NODESET);
        if (nodes == null || nodes.getLength() == 0) {
            return null;
        }
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < nodes.getLength(); i++) {
            String value = nodes.item(i).getTextContent();
            if (!notBlank(value)) {
                continue;
            }
            if (builder.length() > 0) {
                builder.append(separator);
            }
            builder.append(value.trim());
        }
        return builder.length() > 0 ? builder.toString() : null;
    }

    private boolean notBlank(String value) {
        return value != null && !value.trim().isEmpty();
    }

    private String firstNonBlank(String... values) {
        for (String v : values) {
            if (notBlank(v)) {
                return v;
            }
        }
        return null;
    }

    private BigDecimal parseAmount(String value) {
        try {
            return notBlank(value) ? new BigDecimal(value.trim()) : BigDecimal.ZERO;
        } catch (Exception e) {
            return BigDecimal.ZERO;
        }
    }

    private LocalDate parseDateOrToday(String value) {
        try {
            return notBlank(value) ? LocalDate.parse(value.trim()) : LocalDate.now();
        } catch (Exception e) {
            return LocalDate.now();
        }
    }

    private LocalDateTime parseDateTimeOrNow(String value) {
        try {
            if (notBlank(value)) {
                return OffsetDateTime.parse(value.trim()).toLocalDateTime();
            }
        } catch (Exception ignored) {
            try {
                return LocalDateTime.parse(value.trim());
            } catch (Exception ignored2) {
                // fall through
            }
        }
        return LocalDateTime.now();
    }

    private MessageType resolveMessageType(Document doc) {
        String ns = doc.getDocumentElement() != null ? doc.getDocumentElement().getNamespaceURI() : null;
        if (!notBlank(ns) && doc.getDocumentElement() != null) {
            ns = doc.getDocumentElement().getAttribute("xmlns:urn");
        }
        if (!notBlank(ns)) {
            return null;
        }
        Matcher matcher = PACS_CODE_PATTERN.matcher(ns);
        if (!matcher.find()) {
            return null;
        }
        String code = matcher.group(1);
        if ("004".equals(code)) {
            return MessageType.P4;
        }
        if ("008".equals(code)) {
            return MessageType.P8;
        }
        return null;
    }

    private TransferDirection parseDirection(String value) {
        if (!notBlank(value)) {
            return null;
        }
        String normalized = value.trim().toUpperCase();
        if (normalized.contains("OUT")) {
            return TransferDirection.OUT;
        }
        if (normalized.contains("INT")) {
            return TransferDirection.INT;
        }
        if (normalized.contains("IN")) {
            return TransferDirection.IN;
        }
        return null;
    }
}

