    LOAN_NUMBER VARCHAR2(35 CHAR),
    LOAN_YEAR VARCHAR2(4 CHAR),

    DR_STATISTICAL_CODE VARCHAR2(20 CHAR),
    CR_STATISTICAL_CODE VARCHAR2(20 CHAR),
    DEBTOR_CORE_ID VARCHAR2(70 CHAR),
    CREDITOR_CORE_ID VARCHAR2(70 CHAR),
    DEBTOR_LRC VARCHAR2(35 CHAR),
    CREDITOR_LRC VARCHAR2(35 CHAR),
    DEBTOR_SEGMENT VARCHAR2(20 CHAR),
