package rs.unicredit.cbr.service;

import java.util.ArrayList;
import java.util.List;

import java.math.BigDecimal;
import java.util.Optional;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.dto.ValidationApplyResult;
import rs.unicredit.cbr.dto.ValidationEvaluationResult;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrValidationMatrix;
import rs.unicredit.cbr.model.MessageType;
import rs.unicredit.cbr.model.TransferDirection;
import rs.unicredit.cbr.repository.CbrValidationMatrixRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;

@Service
@RequiredArgsConstructor
public class ValidationEvaluationService {

    private static final Logger LOG = LoggerFactory.getLogger(ValidationEvaluationService.class);

    private final CbrValidationMatrixRepository validationMatrixRepository;
    private final CbrTransactionRepository transactionRepository;

    public ValidationEvaluationResult evaluateByValidationNo(CbrTransaction txn, BigDecimal validationNo) {
        if (validationNo == null) {
            return ValidationEvaluationResult.builder()
                    .validationNo(null)
                    .matched(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }
        return validationMatrixRepository.findFirstByValidationNo(validationNo)
                .map(rule -> evaluate(txn, rule))
                .orElseGet(() -> ValidationEvaluationResult.builder()
                        .validationNo(validationNo)
                        .matched(false)
                        .failedConditions(List.of("RULE_NOT_FOUND"))
                        .build());
    }

    public ValidationApplyResult applyActionsByValidationNo(Long transactionId, BigDecimal validationNo) {
        if (transactionId == null) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("TRANSACTION_ID_MISSING"))
                    .build();
        }
        if (validationNo == null) {
            return ValidationApplyResult.builder()
                    .validationNo(null)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }

        Optional<CbrTransaction> txn = transactionRepository.findById(transactionId);
        if (txn.isEmpty()) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("TRANSACTION_NOT_FOUND"))
                    .build();
        }
        /* Uzimam pravilo za koje radim */
        Optional<CbrValidationMatrix> rule = validationMatrixRepository.findFirstByValidationNo(validationNo);
        if (rule.isEmpty()) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("RULE_NOT_FOUND"))
                    .build();
        }

        ValidationEvaluationResult evaluation = evaluate(txn.get(), rule.get());
        if (!evaluation.isMatched()) {
            return ValidationApplyResult.builder()
                    .validationNo(evaluation.getValidationNo())
                    .matched(false)
                    .applied(false)
                    .failedConditions(evaluation.getFailedConditions())
                    .build();
        }
        /*  Primena pravila za tabelu TBL_cbr_transaction */
        String appliedReportType = resolveActionValue(rule.get().getActionReportType(), txn.get());
        boolean appliedReport = false;
        String appliedInstrumentValue = null;
        boolean appliedInstrument = false;
        String appliedSpecialMarkValue = null;
        boolean appliedSpecialMark = false;

        CbrTransaction entity = txn.get();
        if (appliedReportType != null) {
            entity.setReportType(appliedReportType);
            appliedReport = true;
        }
        String actionInstrument = rule.get().getActionInstrument();
        boolean requiresNull = requiresNullIfPresent(actionInstrument);
        // If the directive is present, only apply when current value is empty; otherwise always apply.
        if (requiresNull) {
            if (isBlank(entity.getPaymentInstrument())) {
                appliedInstrumentValue = resolveActionValue(actionInstrument, entity);
                if (appliedInstrumentValue != null) {
                    entity.setPaymentInstrument(appliedInstrumentValue);
                    appliedInstrument = true;
                }
            }
        } else {
            appliedInstrumentValue = resolveActionValue(actionInstrument, entity);
            if (appliedInstrumentValue != null) {
                entity.setPaymentInstrument(appliedInstrumentValue);
                appliedInstrument = true;
            }
        }
        String actionSpecialMark = rule.get().getActionSpecialMark();
        boolean specialMarkRequiresNull = requiresNullIfPresent(actionSpecialMark);
        String specialMarkValue = resolveActionValue(actionSpecialMark, entity);
        String specialMarkSource = null;
        if ("INP8".equalsIgnoreCase(specialMarkValue)) {
            specialMarkSource = resolveRelatedSpecialMark(entity, TransferDirection.IN);
        } else if ("OUTP8".equalsIgnoreCase(specialMarkValue)) {
            specialMarkSource = resolveRelatedSpecialMark(entity, TransferDirection.OUT);
        } else {
            specialMarkSource = specialMarkValue;
        }
        if (!isBlank(specialMarkSource)) {
            if (specialMarkRequiresNull) {
                if (isBlank(entity.getSpecialMark())) {
                    entity.setSpecialMark(specialMarkSource);
                    appliedSpecialMarkValue = specialMarkSource;
                    appliedSpecialMark = true;
                }
            } else {
                entity.setSpecialMark(specialMarkSource);
                appliedSpecialMarkValue = specialMarkSource;
                appliedSpecialMark = true;
            }
        }
        if (appliedReport || appliedInstrument || appliedSpecialMark) {
            transactionRepository.save(entity);
        }

        return ValidationApplyResult.builder()
                .validationNo(evaluation.getValidationNo())
                .matched(true)
                .applied(appliedReport || appliedInstrument || appliedSpecialMark)
                .appliedReportType(appliedReportType)
                .appliedInstrument(appliedInstrument)
                .appliedPaymentInstrument(appliedInstrumentValue)
                .appliedSpecialMark(appliedSpecialMark)
                .appliedSpecialMarkValue(appliedSpecialMarkValue)
                .failedConditions(List.of())
                .build();
    }

    public ValidationEvaluationResult evaluate(CbrTransaction txn, CbrValidationMatrix rule) {
        List<String> failures = new ArrayList<>();

        if (rule == null) {
            failures.add("RULE_MISSING");
            return ValidationEvaluationResult.builder()
                    .matched(false)
                    .failedConditions(failures)
                    .build();
        }

        if (!matches(rule.getCondMessageType(), valueOf(txn != null ? txn.getMessageType() : null))) {
            failures.add("COND_MESSAGE_TYPE");
        }
        if (!matches(rule.getCondDirection(), valueOf(txn != null ? txn.getDirection() : null))) {
            failures.add("COND_DIRECTION");
        }
        if (!matches(rule.getCondDebtorAgentCountry(), bicCountry(txn != null ? txn.getDebtorAgent() : null))) {
            failures.add("COND_DEBTOR_AGENT_COUNTRY");
        }
        if (!matches(rule.getCondDebtorCountry(), normalize(txn != null ? txn.getDebtorCountry() : null))) {
            failures.add("COND_DEBTOR_COUNTRY");
        }
        if (!matches(rule.getCondDebtorResidency(), normalize(txn != null ? txn.getDebtorResidency() : null))) {
            failures.add("COND_DEBTOR_RESIDENCY");
        }
        if (!matches(rule.getCondCreditorResidency(), normalize(txn != null ? txn.getCreditorResidency() : null))) {
            failures.add("COND_CREDITOR_RESIDENCY");
        }
        if (!matches(rule.getCondCreditorCountry(), normalize(txn != null ? txn.getCreditorCountry() : null))) {
            failures.add("COND_CREDITOR_COUNTRY");
        }
        if (!matches(rule.getCondCreditorAgentCountry(), bicCountry(txn != null ? txn.getCreditorAgent() : null))) {
            failures.add("COND_CREDITOR_AGENT_COUNTRY");
        }
        if (requiresOriginalP8ReportType70(rule)) {
            if (!matchesOriginalP8ReportType(txn, "70", TransferDirection.OUT, "60.4")) {
                failures.add("COND_ORIGINAL_P8_REPORT_TYPE_70");
            }
        }
        if (requiresOriginalP8ReportType60(rule)) {
            if (!matchesOriginalP8ReportType(txn, "60", TransferDirection.IN, "70.5")) {
                failures.add("COND_ORIGINAL_P8_REPORT_TYPE_60");
            }
        }
        if (requiresDebtorCreditorSameName(rule)) {
            if (!matchesDebtorCreditorSameName(txn)) {
                failures.add("COND_DEBTOR_CREDITOR_NAME_MATCH");
            }
        }
        if (requiresStatCode340(rule)) {
            if (!matchesStatCode340(txn)) {
                failures.add("COND_STAT_CODE_340");
            }
        }
        if (requiresCreditorLrcPrefix(rule)) {
            if (!matchesCreditorLrcPrefix(txn)) {
                failures.add("COND_CREDITOR_LRC_PREFIX");
            }
        }

        return ValidationEvaluationResult.builder()
                .validationNo(rule.getValidationNo())
                .matched(failures.isEmpty())
                .failedConditions(failures)
                .build();
    }

    private boolean matches(String condition, String actual) {
        if (isBlank(condition)) {
            return true;
        }
        String trimmed = condition.trim();
        if (trimmed.startsWith("<>")) {
            String expected = normalize(trimmed.substring(2));
            return actual != null && !actual.equals(expected);
        }
        if (trimmed.startsWith("=")) {
            String expected = normalize(trimmed.substring(1));
            return actual != null && actual.equals(expected);
        }
        String expected = normalize(trimmed);
        return actual != null && actual.equals(expected);
    }

    private String bicCountry(String bic) {
        if (isBlank(bic)) {
            return null;
        }
        String normalized = bic.trim().toUpperCase();
        if (normalized.length() < 6) {
            return null;
        }
        return normalized.substring(4, 6);
    }

    private String valueOf(Enum<?> value) {
        return value != null ? normalize(value.name()) : null;
    }

    private String normalize(String value) {
        return isBlank(value) ? null : value.trim().toUpperCase();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private String resolveActionValue(String rawValue, CbrTransaction txn) {
        if (isBlank(rawValue)) {
            return null;
        }
        String trimmed = stripNullDirective(rawValue);
        if ("NULL".equalsIgnoreCase(trimmed)) {
            return null;
        }
        if (trimmed.toUpperCase(java.util.Locale.ROOT).startsWith("COALESCE(") && trimmed.endsWith(")")) {
            String inner = trimmed.substring("COALESCE(".length(), trimmed.length() - 1);
            String[] parts = inner.split(",", -1);
            for (String part : parts) {
                String candidate = resolveFieldValue(part, txn);
                if (!isBlank(candidate)) {
                    return candidate;
                }
            }
            return null;
        }
        int parenIdx = trimmed.indexOf('(');
        if (parenIdx > 0) {
            trimmed = trimmed.substring(0, parenIdx).trim();
        }
        return resolveFieldValue(trimmed, txn);
    }

    private String normalizeActionReportType(String rawValue) {
        if (isBlank(rawValue)) {
            return null;
        }
        String trimmed = rawValue.trim();
        if ("NULL".equalsIgnoreCase(trimmed)) {
            return null;
        }
        return trimmed;
    }

    private boolean requiresNullIfPresent(String rawValue) {
        if (isBlank(rawValue)) {
            return false;
        }
        return rawValue.toLowerCase(java.util.Locale.ROOT)
                .contains("(samo ako je trenutna vrednost null)");
    }

    private String stripNullDirective(String rawValue) {
        if (isBlank(rawValue)) {
            return null;
        }
        String trimmed = rawValue.trim();
        String marker = "(samo ako je trenutna vrednost null)";
        int idx = trimmed.toLowerCase(java.util.Locale.ROOT).indexOf(marker);
        if (idx >= 0) {
            return trimmed.substring(0, idx).trim();
        }
        return trimmed;
    }

    private String resolveFieldValue(String token, CbrTransaction txn) {
        if (isBlank(token)) {
            return null;
        }
        String normalized = token.trim().toUpperCase(java.util.Locale.ROOT);
        if ("NULL".equals(normalized)) {
            return null;
        }
        if (txn == null) {
            return null;
        }
        switch (normalized) {
            case "DEBTOR_COUNTRY":
                return txn.getDebtorCountry();
            case "CREDITOR_COUNTRY":
                return txn.getCreditorCountry();
            case "DEBTOR_IBAN":
                return txn.getDebtorIban();
            case "CREDITOR_IBAN":
                return txn.getCreditorIban();
            case "DEBTOR_RESIDENCY":
                return txn.getDebtorResidency();
            case "CREDITOR_RESIDENCY":
                return txn.getCreditorResidency();
            case "PAYMENT_REFERENCE":
                return txn.getPaymentReference();
            case "ORIGINAL_TRANSACTION_ID":
                return txn.getOriginalTransactionId();
            case "SPECIAL_MARK":
                return txn.getSpecialMark();
            case "REPORT_TYPE":
                return txn.getReportType();
            case "PAYMENT_INSTRUMENT":
                return txn.getPaymentInstrument();
            case "CUSTOMER_ID":
                return txn.getCustomerId();
            default:
                return token.trim();
        }
    }

    private boolean requiresOriginalP8ReportType70(CbrValidationMatrix rule) {
        if (rule == null || rule.getValidationNo() == null) {
            return false;
        }
        return rule.getValidationNo().compareTo(new BigDecimal("60.4")) == 0;
    }

    private boolean requiresOriginalP8ReportType60(CbrValidationMatrix rule) {
        if (rule == null || rule.getValidationNo() == null) {
            return false;
        }
        return rule.getValidationNo().compareTo(new BigDecimal("70.5")) == 0;
    }

    private boolean requiresDebtorCreditorSameName(CbrValidationMatrix rule) {
        if (rule == null || rule.getValidationNo() == null) {
            return false;
        }
        return rule.getValidationNo().compareTo(new BigDecimal("66.6")) == 0
                || rule.getValidationNo().compareTo(new BigDecimal("77.5")) == 0;
    }

    private boolean requiresStatCode340(CbrValidationMatrix rule) {
        if (rule == null || rule.getValidationNo() == null) {
            return false;
        }
        return rule.getValidationNo().compareTo(new BigDecimal("70.3")) == 0
                || rule.getValidationNo().compareTo(new BigDecimal("70.4")) == 0;
    }

    private boolean requiresCreditorLrcPrefix(CbrValidationMatrix rule) {
        if (rule == null || rule.getValidationNo() == null) {
            return false;
        }
        return rule.getValidationNo().compareTo(new BigDecimal("66.4")) == 0;
    }

    private boolean matchesDebtorCreditorSameName(CbrTransaction txn) {
        if (txn == null) {
            return false;
        }
        String debtorName = normalize(txn.getDebtorName());
        String creditorName = normalize(txn.getCreditorName());
        return debtorName != null && debtorName.equals(creditorName);
    }

    private boolean matchesStatCode340(CbrTransaction txn) {
        if (txn == null) {
            return false;
        }
        if ("340".equals(normalize(txn.getCrStatisticalCode()))
                || "340".equals(normalize(txn.getDrStatisticalCode()))) {
            return true;
        }
        if (txn.getRegulatoryDetails() == null || txn.getRegulatoryDetails().isEmpty()) {
            return false;
        }
        return txn.getRegulatoryDetails().stream()
                .anyMatch(stat -> "340".equals(normalize(stat.getSplitStatCode())));
    }

    private boolean matchesCreditorLrcPrefix(CbrTransaction txn) {
        if (txn == null || isBlank(txn.getCreditorLrc())) {
            return false;
        }
        String normalized = txn.getCreditorLrc().trim();
        return normalized.startsWith("509") || normalized.startsWith("538");
    }

    private boolean matchesOriginalP8ReportType(
            CbrTransaction txn, String expectedReportType, TransferDirection direction, String validationNo) {
        if (txn == null) {
            return false;
        }
        if (isBlank(txn.getOriginalTransactionId())) {
            LOG.info("Validation {} skipped: missing originalTransactionId on txn id={}", validationNo, txn.getId());
            return false;
        }
        if (txn.getOriginalSettlementDate() == null) {
            LOG.info("Validation {} skipped: missing originalSettlementDate on txn id={}", validationNo, txn.getId());
            return false;
        }
        Optional<CbrTransaction> originalP8 = transactionRepository
                .findFirstByPaymentReferenceAndSettlementDateAndDirectionAndMessageType(
                        txn.getOriginalTransactionId(), txn.getOriginalSettlementDate(),
                        direction, MessageType.P8);
        if (originalP8.isEmpty()) {
            LOG.info("Validation {} skipped: no original P8 found (origTxId={}, origSettlDate={})",
                    validationNo, txn.getOriginalTransactionId(), txn.getOriginalSettlementDate());
            return false;
        }
        return expectedReportType.equalsIgnoreCase(originalP8.get().getReportType());
    }

    private String resolveRelatedSpecialMark(CbrTransaction entity, TransferDirection direction) {
        if (entity == null || direction == null) {
            return null;
        }
        String originalTransactionId = entity.getOriginalTransactionId();
        if (isBlank(originalTransactionId)) {
            LOG.info("Special mark lookup skipped: missing originalTransactionId on txn id={}", entity.getId());
            return null;
        }
        if (entity.getOriginalSettlementDate() == null) {
            LOG.info("Special mark lookup skipped: missing originalSettlementDate on txn id={}", entity.getId());
            return null;
        }
        Optional<CbrTransaction> related = transactionRepository
                .findFirstByPaymentReferenceAndSettlementDateAndDirectionAndMessageType(
                        originalTransactionId, entity.getOriginalSettlementDate(), direction, MessageType.P8);
        if (related.isEmpty()) {
            LOG.info("Special mark lookup: no related P8 txn found (origTxId={}, direction={})",
                    originalTransactionId, direction);
            return null;
        }
        return related.get().getSpecialMark();
    }
}

