+package rs.unicredit.cbr.mq;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.jms.annotation.JmsListener;
+import org.springframework.jms.support.JmsHeaders;
+import org.springframework.messaging.handler.annotation.Header;
+import org.springframework.stereotype.Component;
+
+import rs.unicredit.cbr.model.CbrTransactionRequest;
+import rs.unicredit.cbr.model.SkipperTransactionRequest;
+import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;
+import rs.unicredit.cbr.repository.SkipperTransactionRequestRepository;
+
+@Component
+public class SkipperMqListener {
+
+    private static final Logger LOG = LoggerFactory.getLogger(SkipperMqListener.class);
+
+    private final SkipperTransactionRequestRepository skipperRepository;
+    private final CbrTransactionRequestRepository cbrRequestRepository;
+
+    public SkipperMqListener(
+            SkipperTransactionRequestRepository skipperRepository,
+            CbrTransactionRequestRepository cbrRequestRepository) {
+        this.skipperRepository = skipperRepository;
+        this.cbrRequestRepository = cbrRequestRepository;
+    }
+
+    @JmsListener(destination = "${customs.mq.inbound-queue}", containerFactory = "mqListenerContainerFactory")
+    public void onMessage(String payload, @Header(name = JmsHeaders.CORRELATION_ID, required = false) String correlationId) {
+        SkipperTransactionRequest skipperRequest = new SkipperTransactionRequest();
+        skipperRequest.setSourceSystem("SKIPPER_MQ");
+        skipperRequest.setRawXml(payload);
+        skipperRequest.setStatus("S1");
+        skipperRepository.save(skipperRequest);
+
+        if (correlationId == null || correlationId.isBlank()) {
+            LOG.info("Received Skipper message without correlationId; stored as skipperRequestId={}",
+                    skipperRequest.getId());
+            return;
+        }
+        try {
+            Long requestId = Long.valueOf(correlationId);
+            cbrRequestRepository.findById(requestId).ifPresent(request -> {
+                request.setStatus("S5");
+                cbrRequestRepository.save(request);
+            });
+        } catch (NumberFormatException e) {
+            LOG.info("Received Skipper message with non-numeric correlationId={}", correlationId);
+        }
+    }
+}
