@RestController
@RequestMapping("/api/cbr")
@RequiredArgsConstructor
public class CbrIngestionController {

    private final CbrIngestionService ingestionService;
    private final GetClientForSepaService getClientForSepaService;
    private final ValidationEvaluationService validationEvaluationService;
    private final CbrTransactionRepository transactionRepository;
    private final ObjectProvider<MqMessageService> mqMessageService;

    @PostMapping("/transactions/ingest")
    public ResponseEntity<CbrTransaction> ingest(@Validated @RequestBody CbrIngestRequest request) {
        CbrTransaction saved = ingestionService.ingest(request);
        return ResponseEntity.ok(saved);
    }

    @GetMapping("/clients/sepa")
    public ResponseEntity<GetClientForSepaResponse.ClientData> getClientForSepa(
            @RequestParam("p_account") String account,
            @RequestParam("request_id") Long requestId,
            @RequestParam(value = "p_bic", required = false) String bic,
            @RequestParam(value = "role", required = false) GetClientForSepaService.AccountRole role) {
        GetClientForSepaService.AccountRole resolvedRole =
                role != null ? role : GetClientForSepaService.AccountRole.DEBTOR;
        return ResponseEntity.ok(
                getClientForSepaService.fetchAndUpdateByAccount(account, bic, requestId, resolvedRole));
    }

    @GetMapping("/validations/check")
    public ResponseEntity<ValidationEvaluationResult> validateByValidationNo(
            @RequestParam("transaction_id") Long transactionId,
            @RequestParam("validation_no") BigDecimal validationNo) {
        return transactionRepository.findById(transactionId)
                .map(txn -> ResponseEntity.ok(
                        validationEvaluationService.evaluateByValidationNo(txn, validationNo)))
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @PostMapping("/validations/apply")
    public ResponseEntity<ValidationApplyResult> applyValidationActions(
